use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::Path,process::Command,collections::BTreeMap};
const R:&str="/home/ubuntu/src/zopro-perf-work/g1-control-codegen176";
fn h(b:&[u8])->String{format!("{:x}",Sha256::digest(b))}
fn main(){assert!(!Path::new(R).join("analysis.json").exists());let mut rows=BTreeMap::<String,Value>::new();
 for(label,p,sha)in[
  ("original","/home/ubuntu/src/zopro-perf-work/g2-denominator-tree176/control-bin","f07229ce665cf61c972037a27752bb53cce8c5dd58be0c71d8776434c961064b"),
  ("two_chain_control","/home/ubuntu/src/zopro-perf-work/g2-two-chain-stream176/candidate-bin","19a37c35830e0300a3040fc9d82a3b16d384ed0560a218c779dd375aed399c91"),
  ("descriptor_control","/home/ubuntu/src/zopro-perf-work/g2-descriptor-chunks176/candidate-bin","740708e5ab03491c26b5db4e843b0af95c5a6bdf2c9634652b514d6471dfd99c")]{
  assert_eq!(h(&fs::read(p).unwrap()),sha);let d=Path::new(R).join(label);fs::create_dir(&d).unwrap();let argv=["-S","--size-sort",p];let nm=Command::new("nm").args(argv).output().unwrap();assert!(nm.status.success());fs::write(d.join("nm.stdout"),&nm.stdout).unwrap();fs::write(d.join("nm.stderr"),&nm.stderr).unwrap();let n=String::from_utf8(nm.stdout.clone()).unwrap();
  let symbols=n.lines().filter_map(|l|{let f=l.split_whitespace().collect::<Vec<_>>();if f.len()!=4{return None}let name=rustc_demangle::try_demangle(f[3]).map(|d|format!("{d:#}")).unwrap_or(f[3].into());if name.contains("::msm::stream_g1_impl::<"){Some((f[3],name,u64::from_str_radix(f[0],16).unwrap(),u64::from_str_radix(f[1],16).unwrap()))}else{None}}).collect::<Vec<_>>();assert_eq!(symbols.len(),1);let(raw,name,address,size)=&symbols[0];
  let arg=format!("--disassemble={raw}");let args=["-d","--no-show-raw-insn",&arg,p];let o=Command::new("objdump").args(args).output().unwrap();assert!(o.status.success());fs::write(d.join("assembly.txt"),&o.stdout).unwrap();fs::write(d.join("objdump.stderr"),&o.stderr).unwrap();let s=String::from_utf8(o.stdout.clone()).unwrap();let(mut instructions,mut ifma,mut rsp,mut branches,mut bounds)=(0,0,0,0,0);
  for line in s.lines(){let Some((a,t))=line.trim().split_once(':')else{continue};if a.is_empty()||!a.chars().all(|c|c.is_ascii_hexdigit()){continue}let Some(m)=t.split_whitespace().next()else{continue};instructions+=1;if m.starts_with("vpmadd52"){ifma+=1}if t.contains("(%rsp)"){rsp+=1}if m.starts_with('j')&&m!="jmp"{branches+=1}if m=="call"&&t.contains("panic_bounds_check"){bounds+=1}}
  rows.insert(label.into(),json!({"binary":p,"binary_sha256":sha,"symbol":name,"address":address,"bytes":size,"instruction_sites":instructions,"IFMA_sites":ifma,"RSP_operand_lines":rsp,"conditional_jump_sites":branches,"bounds_panic_call_sites":bounds,"nm":{"argv":argv,"exit":0,"stdout_sha256":h(&nm.stdout),"stderr_sha256":h(&nm.stderr)},"objdump":{"argv":args,"exit":0,"stdout_sha256":h(&o.stdout),"stderr_sha256":h(&o.stderr)}}));
 }
 let result=json!({"scope":"read-only linked G1 source-control comparison; no new timing or causal inference","rows":rows,"new_proofs":0,"new_performance_recordings":0});fs::write(format!("{R}/analysis.json"),serde_json::to_vec_pretty(&result).unwrap()).unwrap();for(k,v)in rows{println!("{k}: bytes={} instruction_sites={} IFMA={} RSP={} branches={} bounds={}",v["bytes"],v["instruction_sites"],v["IFMA_sites"],v["RSP_operand_lines"],v["conditional_jump_sites"],v["bounds_panic_call_sites"]);}
}
